excels.excel:

EXPORT WITH SHEET="差旅费用报销明细", HEADER=true,
    MAPPING={"a":"出差人","b":"出差事由","c":"出发日期","d":"返回日期","e":"交通费","f":"住宿费","g":"补贴","h":"小计"},
    FORMAT={"c":"yyyy-MM-dd","d":"yyyy-MM-dd","e":"#,##0.00","f":"#,##0.00","g":"#,##0.00","h":"#,##0.00"},
    FORMULAS={
        H2:'E2+F2+G2',H3:'E3+F3+G3',H4:'E4+F4+G4',H5:'E5+F5+G5',H6:'E6+F6+G6',
        E7:'SUM(E2:E6)',F7:'SUM(F2:F6)',G7:'SUM(G2:G6)',H7:'SUM(H2:H6)'
    },
    STYLE={ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}}
